import{Q as e,V as t,ht as n,nt as r,rt as i,tt as a,zt as o}from"./chunks/framework.wxcks8ca.js";var s=JSON.parse(`{"title":"内置工具","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/reference/tools.md","filePath":"zh/kimi-code-cli/reference/tools.md"}`),c={name:`kimi-code-cli/reference/tools.md`};function l(t,s,c,l,u,d){return n(),a(`div`,null,[s[9]||=r(`<h1 id="内置工具" tabindex="-1">内置工具 <a class="header-anchor" href="#内置工具" aria-label="Permalink to “内置工具”">​</a></h1><p>内置工具是 Kimi Code CLI 随核心引擎提供的工具集，无需安装 MCP server 即可使用。Agent 在每次对话中会根据任务需要自动选择并调用这些工具；用户可以通过权限审批界面查看每次工具调用的细节。</p><p>与 MCP 工具相比，内置工具由运行时直接管理，生命周期与会话绑定，无需外部进程。两者都遵循统一的审批机制：<strong>只读类工具</strong>（如 <code>Read</code>、<code>Grep</code>、<code>Glob</code>）默认自动放行，<strong>写入与执行类工具</strong>（如 <code>Write</code>、<code>Edit</code>、<code>Bash</code>）默认需要用户审批。YOLO 模式下普通工具调用的审批会被跳过，但 Plan 模式下的退出审批不受影响。</p><h2 id="文件类" tabindex="-1">文件类 <a class="header-anchor" href="#文件类" aria-label="Permalink to “文件类”">​</a></h2><p>文件类工具负责读取、写入、搜索本地文件系统，是代码分析和修改任务的基础工具。</p><table tabindex="0"><thead><tr><th>工具</th><th>默认审批</th><th>说明</th></tr></thead><tbody><tr><td><code>Read</code></td><td>自动放行</td><td>读取文本文件内容</td></tr><tr><td><code>Write</code></td><td>需审批</td><td>创建或覆盖文件</td></tr><tr><td><code>Edit</code></td><td>需审批</td><td>精确字符串替换</td></tr><tr><td><code>Grep</code></td><td>自动放行</td><td>基于 ripgrep 的全文搜索</td></tr><tr><td><code>Glob</code></td><td>自动放行</td><td>按 glob 模式查找文件</td></tr><tr><td><code>ReadMediaFile</code></td><td>自动放行</td><td>读取图片或视频文件</td></tr></tbody></table><p><strong><code>Read</code></strong> 接受文件路径（<code>path</code>）以及可选的 <code>line_offset</code>（起始行号，支持负数从末尾倒数）和 <code>n_lines</code>（读取行数上限）。单次最多返回 1000 行或 100 KB，超出部分会附带截断提示。如果文件是图片或视频，工具会提示改用 <code>ReadMediaFile</code>。</p><p><strong><code>Write</code></strong> 接受 <code>path</code>、<code>content</code> 和可选的 <code>mode</code>（<code>overwrite</code> 或 <code>append</code>，默认覆盖）。缺失的父目录会自动创建；<code>append</code> 模式将内容追加到文件末尾，不自动添加换行。</p><p><strong><code>Edit</code></strong> 接受 <code>path</code>、<code>old_string</code>（要替换的精确文本）和 <code>new_string</code>（替换后的文本）。默认只替换唯一一处匹配，若文件中存在多处相同内容会报错并提示使用 <code>replace_all: true</code>。<code>old_string</code> 与 <code>new_string</code> 不能相同。</p><p><strong><code>Grep</code></strong> 调用 ripgrep 搜索文件内容，支持正则表达式（<code>pattern</code>）、搜索路径（<code>path</code>）、文件类型过滤（<code>type</code>，如 <code>ts</code>、<code>py</code>）、glob 过滤（<code>glob</code>）和输出模式（<code>output_mode</code>：<code>files_with_matches</code> / <code>content</code> / <code>count_matches</code>，默认 <code>files_with_matches</code>）。<code>content</code> 模式支持上下文行（<code>-A</code>、<code>-B</code>、<code>-C</code>）、忽略大小写（<code>-i</code>）、行号（<code>-n</code>，默认 true）、跨行匹配（<code>multiline</code>）。所有模式支持 <code>offset</code> + <code>head_limit</code> 分页，<code>head_limit</code> 默认 250、传 0 表示不限。<code>.env</code>、私钥等敏感文件会被自动过滤；<code>include_ignored=true</code> 可搜索被 <code>.gitignore</code> 忽略的文件，但敏感文件仍保持过滤。</p><p><strong><code>Glob</code></strong> 按 glob 模式（<code>pattern</code>）在指定目录（<code>path</code>，默认工作目录）中匹配文件，结果按修改时间倒序排列，最多返回 100 条。默认尊重 <code>.gitignore</code>、<code>.ignore</code> 和 <code>.rgignore</code>；设置 <code>include_ignored=true</code> 可包含构建产物等被忽略的文件，但敏感文件仍会被过滤。支持 <code>*.{ts,tsx}</code> 这类花括号模式，也允许宽泛通配符模式，但通常会在匹配上限处截断。</p><p><strong><code>ReadMediaFile</code></strong> 将图片或视频以多模态内容发送给模型。它接受 <code>path</code>，以及 <code>region</code>、<code>full_resolution</code> 等可选的图片细节参数；文件大小上限为 100 MB。默认读图会按配置的模型限制压缩；如果自动压缩无法安全满足限制，工具会返回错误且不发送原图，并提示模型先创建更小的副本再读取。是否可用取决于当前模型的视觉能力（<code>image_in</code> / <code>video_in</code>）。</p><h2 id="shell" tabindex="-1">Shell <a class="header-anchor" href="#shell" aria-label="Permalink to “Shell”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>默认审批</th><th>说明</th></tr></thead><tbody><tr><td><code>Bash</code></td><td>需审批</td><td>执行 Shell 命令</td></tr></tbody></table><p><strong><code>Bash</code></strong> 是权限要求最严格的工具，也是功能最通用的工具。参数：</p><ul><li><code>command</code>（必填）：要执行的 Shell 命令</li><li><code>cwd</code>：工作目录</li><li><code>timeout</code>：超时时间（毫秒）；前台默认 60 秒、最长 5 分钟</li><li><code>run_in_background</code>：是否以后台任务运行；后台默认 10 分钟超时（print 模式 <code>kimi -p</code> 下默认无超时）</li><li><code>description</code>：后台任务描述，<code>run_in_background=true</code> 时必填</li><li><code>disable_timeout</code>：后台任务是否取消超时限制</li></ul><p>前台模式会阻塞当前轮次，直到命令结束或超时；命令运行期间，TUI 会把 stdout 和 stderr 流式显示在正在运行的 <code>Bash</code> 工具卡片中。前台命令超时后默认不会被终止，而是转为后台任务继续运行（受 600 秒默认后台超时约束）；如需恢复超时即终止的行为，将 <code>[background]</code> 的 <a href="/code/docs/kimi-code-cli/configuration/config-files.html#background"><code>bash_auto_background_on_timeout</code></a> 设为 <code>false</code>。600 秒的默认后台超时可通过 <a href="/code/docs/kimi-code-cli/configuration/config-files.html#background"><code>bash_task_timeout_s</code></a> 配置（<code>0</code> = 无超时），且在 print 模式（<code>kimi -p</code>）下默认无超时。后台模式立即返回任务 ID，任务结束时自动通知 Agent。stdin 始终被关闭，交互式命令会立即收到 EOF。任务被停止或后台超时时采用两阶段终止策略（SIGTERM → 5 秒宽限期 → SIGKILL），确保进程可靠结束。Windows 平台默认使用 Git Bash。</p><h2 id="网络类" tabindex="-1">网络类 <a class="header-anchor" href="#网络类" aria-label="Permalink to “网络类”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>默认审批</th><th>说明</th></tr></thead><tbody><tr><td><code>WebSearch</code></td><td>自动放行</td><td>网络搜索</td></tr><tr><td><code>FetchURL</code></td><td>自动放行</td><td>获取指定 URL 的内容</td></tr></tbody></table><p><strong><code>WebSearch</code></strong> 接受 <code>query</code>（搜索词）。需要宿主提供搜索实现，未注入时不会出现在工具列表中。</p><p><strong><code>FetchURL</code></strong> 接受单个 <code>url</code> 参数，返回页面内容。对 HTML 页面，宿主会提取正文而非返回完整 HTML；纯文本或 Markdown 页面直接透传。同样需要宿主注入实现。</p><h2 id="plan-模式" tabindex="-1">Plan 模式 <a class="header-anchor" href="#plan-模式" aria-label="Permalink to “Plan 模式”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>默认审批</th><th>说明</th></tr></thead><tbody><tr><td><code>EnterPlanMode</code></td><td>自动放行</td><td>进入 Plan 模式</td></tr><tr><td><code>ExitPlanMode</code></td><td>自动放行（需用户确认计划）</td><td>退出 Plan 模式并提交计划</td></tr></tbody></table><p>Plan 模式是一种受约束的工作状态：进入后 <code>Write</code> 与 <code>Edit</code> 只允许写入当前的计划文件，<code>TaskStop</code> 被完全拦截。其余工具（包括 <code>Bash</code>）仍按当前权限规则处理。</p><p><strong><code>EnterPlanMode</code></strong> 不接受任何参数，进入成功后返回工作流指引及计划文件路径。</p><p><strong><code>ExitPlanMode</code></strong> 读取当前计划文件内容，将计划呈现给用户审批后退出 Plan 模式。可选参数 <code>options</code> 允许 Agent 提供 1–3 个备选方案（每项含 <code>label</code> 与 <code>description</code>，<code>label</code> 最长 80 字符），供用户在审批时选择；<code>label</code> 不能重复，也不能使用 <code>Approve</code>、<code>Reject</code>、<code>Reject and Exit</code>、<code>Revise</code> 等保留词。</p><h2 id="状态管理" tabindex="-1">状态管理 <a class="header-anchor" href="#状态管理" aria-label="Permalink to “状态管理”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>默认审批</th><th>说明</th></tr></thead><tbody><tr><td><code>TodoList</code></td><td>自动放行</td><td>管理任务待办列表</td></tr></tbody></table><p><strong><code>TodoList</code></strong> 在多步骤操作中维护一份可见的子任务列表，状态存储在 Agent 会话内。<code>todos</code> 参数接受一个数组，每项含 <code>title</code> 和 <code>status</code>（<code>pending</code> / <code>in_progress</code> / <code>done</code>）；省略 <code>todos</code> 则仅查询当前列表，传入空数组则清空列表。</p><h2 id="协作类" tabindex="-1">协作类 <a class="header-anchor" href="#协作类" aria-label="Permalink to “协作类”">​</a></h2><p>协作类工具负责 Agent 间协作、用户交互和 Skill 调用。</p><table tabindex="0"><thead><tr><th>工具</th><th>默认审批</th><th>说明</th></tr></thead><tbody><tr><td><code>Agent</code></td><td>自动放行</td><td>派生子 Agent 执行子任务</td></tr><tr><td><code>AgentSwarm</code></td><td>swarm mode 中自动放行，否则需审批</td><td>启动基于 item 的子 Agent，或恢复已有子 Agent</td></tr><tr><td><code>AskUserQuestion</code></td><td>自动放行</td><td>向用户提问以获取结构化输入</td></tr><tr><td><code>Skill</code></td><td>自动放行</td><td>调用已注册的 inline Skill</td></tr></tbody></table><p><strong><code>Agent</code></strong> 将子任务委托给子 Agent 执行。必填参数：<code>prompt</code>（完整任务描述）和 <code>description</code>（3–5 个词的简短说明）。可选参数：<code>subagent_type</code>（默认 <code>coder</code>）、<code>resume</code>（恢复已有 Agent 的 ID，与 <code>subagent_type</code> 互斥）、<code>run_in_background</code>（默认 false）和 <code>model</code>（<code>&quot;secondary&quot;</code> 表示 <code>[secondary_model] model</code> 配置的次主力模型，<code>&quot;primary&quot;</code> 表示主模型；resume 时无效；在 <code>kimi web</code> 或实验性 <code>kimi -p</code> 下启用次主力模型实验功能后可用，TUI 下被忽略）。显式 <code>model</code> 会覆盖所选 <a href="/code/docs/kimi-code-cli/customization/agents.html#agent-文件格式">Agent profile 的 <code>model_preference</code></a>；两者均未设置时，已配置的次主力模型为默认值，未配置时则继承调用方模型。Agent 任务默认 2 小时超时，可通过 <code>config.toml</code> 的 <code>[subagent] timeout_ms</code>（<code>0</code> = 无超时，或 <code>KIMI_SUBAGENT_TIMEOUT_MS</code> 环境变量）配置，且在 print 模式（<code>kimi -p</code>）下默认无超时。前台模式下父 Agent 等待子 Agent 完成再继续；后台模式立即返回任务 ID，完成时通过合成 User 消息自动回到主 Agent。多个前台 <code>Agent</code> 调用在同一步运行时，TUI 会合并展示，并为每个子 Agent 显示运行、等待、完成或失败状态以及已耗时长。子 Agent 体系细节见 <a href="/code/docs/kimi-code-cli/customization/agents.html">Agent 与子 Agent</a>。</p>`,33),e(`p`,null,[s[0]||=e(`strong`,null,[e(`code`,null,`AgentSwarm`)],-1),s[1]||=i(` 可以从共享的 `,-1),s[2]||=e(`code`,null,`prompt_template`,-1),s[3]||=i(` 和 `,-1),s[4]||=e(`code`,null,`items`,-1),s[5]||=i(` 数组启动子 Agent，也可以通过 `,-1),s[6]||=e(`code`,null,`resume_agent_ids`,-1),s[7]||=i(` 恢复已有子 Agent，或在一次调用中同时使用两者。模板必须包含 `,-1),e(`code`,null,o(t.item),1),s[8]||=r(` 占位符；每个 item 会替换该占位符，并启动一个新的子 Agent。传入 <code>subagent_type</code> 可以指定整个 swarm 中所有新启动的子 Agent 使用的 profile；省略时默认使用 <code>coder</code>。传入 <code>model</code>（在 <code>kimi web</code> 或实验性 <code>kimi -p</code> 下启用次主力模型实验功能后可用，TUI 下被忽略）可以让新启动的子 Agent 运行在 <code>[secondary_model] model</code> 配置的次主力模型（<code>&quot;secondary&quot;</code>）或主模型（<code>&quot;primary&quot;</code>）上。这项显式选择会覆盖所选 <a href="/code/docs/kimi-code-cli/customization/agents.html#agent-文件格式">Agent profile 的 <code>model_preference</code></a>；两者均未设置时，已配置的次主力模型为默认值，未配置时则继承调用方模型。恢复的子 Agent 保持其原有模型。不传 <code>resume_agent_ids</code> 时，本工具要求至少 2 个 item；传入 <code>resume_agent_ids</code> 时，可以恢复 1 个或多个已有子 Agent。本工具最多支持 128 个子 Agent，会等待全部子 Agent 完成，并返回聚合报告。在 TUI 中，前台 swarm 会在输入框上方显示实时 <code>Agent swarm</code> 进度面板。若一次模型响应调用 <code>AgentSwarm</code>，该调用必须是该响应中的唯一工具调用；如需运行多个 swarm，应先调用一个 <code>AgentSwarm</code> 并等待结果，再调用下一个，若单个模板可以覆盖这些工作，也可以合并为一个 swarm。在 <code>manual</code> 权限模式下，未处于 swarm mode 时调用 <code>AgentSwarm</code> 会触发审批，除非已有权限规则允许；swarm mode 已开启时，<code>AgentSwarm</code> 本身会自动放行。权限规则只能按工具名 <code>AgentSwarm</code> 匹配，不支持 <code>AgentSwarm(swarm)</code> 这类参数模式。默认情况下，本工具会逐步提升并发且不设上限（立即启动 5 个子 Agent，之后每 700 毫秒再启动 1 个）；将 <code>KIMI_CODE_AGENT_SWARM_MAX_CONCURRENCY</code> 设为正整数可限制该阶段同时运行的子 Agent 数量，不设置则表示不限制。若设置为非正整数的值，本次 AgentSwarm 调用会立即失败。`,41)]),s[10]||=r(`<p><strong><code>AskUserQuestion</code></strong> 以结构化多选题的形式向用户提问，适用于需要消歧或选择方案的场景。<code>questions</code> 参数接受 1–4 道题，每道题需提供 <code>question</code>（以 <code>?</code> 结尾）、<code>options</code>（2–4 个选项，每项含 <code>label</code> 和 <code>description</code>）以及可选的 <code>header</code>（最多 12 字符）和 <code>multi_select</code>（默认 false）。系统自动附加&quot;其他&quot;选项。<code>background</code> 为 true 时启动后台问题任务并立即返回任务 ID。宿主未实现交互式提问能力时返回失败提示，Agent 应改为在文本回复中直接提问。</p><p><strong><code>Skill</code></strong> 允许 Agent 主动调用已注册的 inline 类型 Skill。接受 <code>skill</code>（Skill 名称）和可选的 <code>args</code>（附加参数文本）。只有 <code>type = &quot;inline&quot;</code> 的 Skill 能通过此工具调用；<code>disableModelInvocation: true</code> 的 Skill 会被拒绝。嵌套调用深度上限 3 层。Skill 体系细节见 <a href="/code/docs/kimi-code-cli/customization/skills.html">Agent Skills</a>。</p><h2 id="后台任务" tabindex="-1">后台任务 <a class="header-anchor" href="#后台任务" aria-label="Permalink to “后台任务”">​</a></h2><p>后台任务工具用于管理通过 <code>Bash</code>、<code>Agent</code> 或 <code>AskUserQuestion</code> 启动的后台任务。任务进入终止状态时会自动把状态和已保存的输出路径送回 Agent；如需提前检查进度，使用 <code>TaskOutput</code>。</p><table tabindex="0"><thead><tr><th>工具</th><th>默认审批</th><th>说明</th></tr></thead><tbody><tr><td><code>TaskList</code></td><td>自动放行</td><td>列出后台任务</td></tr><tr><td><code>TaskOutput</code></td><td>自动放行</td><td>查看后台任务的输出</td></tr><tr><td><code>TaskStop</code></td><td>需审批</td><td>停止正在运行的后台任务</td></tr></tbody></table><p><strong><code>TaskList</code></strong> 返回后台任务列表。可选参数 <code>active_only</code>（默认 true，仅列出运行中的任务）和 <code>limit</code>（默认 20，取值范围 1–100）。</p><p><strong><code>TaskOutput</code></strong> 根据 <code>task_id</code> 返回任务状态与输出。内联预览最多包含最近 32 KB 的内容；完整日志保存在磁盘上，工具会一并返回 <code>output_path</code> 并提示通过 <code>Read</code> 分页读取。可选 <code>block</code>（默认 false）和 <code>timeout</code>（等待秒数，默认 30，取值范围 0–3600）参数可用于等待任务完成后再返回。</p><p><strong><code>TaskStop</code></strong> 接受 <code>task_id</code> 和可选的 <code>reason</code>（默认 <code>Stopped by TaskStop</code>）。对已处于终止状态的任务也能安全调用。</p><h2 id="定时任务" tabindex="-1">定时任务 <a class="header-anchor" href="#定时任务" aria-label="Permalink to “定时任务”">​</a></h2><p>定时任务工具允许 Agent 把一段 prompt 在未来某个时间重新注入到当前会话——既可以是一次性提醒，也可以是按 cron 周期触发的任务（定期巡检、每日报表、部署监控等）。计划绑定到会话，用 <code>kimi --session</code> 恢复会话后仍然有效，但不会带入全新的会话。单个会话最多保留 50 个生效中的定时任务。设置 <code>KIMI_DISABLE_CRON=1</code> 可整体禁用，详见<a href="/code/docs/kimi-code-cli/configuration/env-vars.html#运行时开关">环境变量</a>。</p><table tabindex="0"><thead><tr><th>工具</th><th>默认审批</th><th>说明</th></tr></thead><tbody><tr><td><code>CronCreate</code></td><td>需审批</td><td>安排一个在未来时刻触发的 prompt</td></tr><tr><td><code>CronList</code></td><td>自动放行</td><td>列出已安排的定时任务</td></tr><tr><td><code>CronDelete</code></td><td>需审批</td><td>取消已安排的定时任务</td></tr></tbody></table><p><strong><code>CronCreate</code></strong> 接受 <code>cron</code>（用户本地时区下标准的 5 段 cron 表达式：<code>minute hour day-of-month month day-of-week</code>）、<code>prompt</code>（触发时要注入的文本，UTF-8 上限 8 KB）以及可选的 <code>recurring</code>（默认 <code>true</code>；传 <code>false</code> 表示一次性提醒，触发后自动删除）。成功时返回 8 位 16 进制 <code>id</code>、人类可读的 <code>humanSchedule</code>（如 <code>every 5 minutes</code>）和 <code>nextFireAt</code>（下次触发时间的 ISO 时间戳）。</p><p>为避免整批用户在整点同时触发，调度器会做确定性抖动：周期任务向后偏移 <code>min(周期的 10%, 15 分钟)</code>；一次性任务若恰好落在 <code>:00</code> 或 <code>:30</code> 则向前提前最多 90 秒。如果调度器错过了若干触发时刻（如笔记本合盖），唤醒后只会触发一次，prompt 会包裹在 <code>&lt;cron-fire&gt;</code> 信封里并附带 <code>coalescedCount</code>。周期任务存活超过 7 天后会以 <code>stale=&quot;true&quot;</code> 做最后一次触发后自动删除；想继续保留时，再次调用 <code>CronCreate</code> 即可。</p><p><strong><code>CronList</code></strong> 是只读工具，不接受任何参数。为每个生效中的任务返回一条记录，字段包括 <code>id</code>、<code>cron</code>、<code>humanSchedule</code>、<code>nextFireAt</code>、<code>recurring</code>、<code>ageDays</code> 和 <code>stale</code>。记录用 <code>---</code> 分隔，按调度时间排列。</p><p><strong><code>CronDelete</code></strong> 只接受一个 <code>id</code>。对周期任务，未来所有触发立即停止；对一次性任务，挂起的那次触发会被取消。已触发的一次性任务会自动删除，因此对已触发过的一次性任务调用 <code>CronDelete</code> 会返回 <code>No cron job with id ...</code>。删除不可撤销，需要还原时只能再次 <code>CronCreate</code>。<code>CronDelete</code> 在 Plan 模式下同样会被拦截。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/customization/agents.html">Agent 与子 Agent</a> — <code>Agent</code> 工具的调度机制与上下文隔离</li><li><a href="/code/docs/kimi-code-cli/customization/hooks.html">Hooks</a> — 在工具调用前后触发本地脚本</li><li><a href="/code/docs/kimi-code-cli/reference/slash-commands.html">斜杠命令</a> — TUI 内置控制命令速查</li></ul>`,17)])}var u=t(c,[[`render`,l]]);export{s as __pageData,u as default};